package warranty

import (
	"errors"
	"testing"
	"time"
)

func setupUseStore(t *testing.T) (*Store, time.Time) {
	t.Helper()
	s := NewStore()
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	if err := s.RegisterProduct("p1", base, 365, nil); err != nil {
		t.Fatal(err)
	}
	if err := s.RegisterPart("part1", 10); err != nil {
		t.Fatal(err)
	}
	if err := s.SubmitRequest("r1", "p1", "F1"); err != nil {
		t.Fatal(err)
	}
	now := base.Add(time.Hour)
	expiry := now.Add(24 * time.Hour)
	if _, err := s.Reserve("c1", "r1", "part1", 5, expiry, now); err != nil {
		t.Fatal(err)
	}
	if _, err := s.Reserve("c2", "r1", "part1", 3, expiry, now); err != nil {
		t.Fatal(err)
	}
	return s, now
}

func TestUseConflictClassification(t *testing.T) {
	s, now := setupUseStore(t)
	if _, err := s.Use("u1", "c1", 2, now); err != nil {
		t.Fatal(err)
	}
	// 改数量为零/负数 → ErrConflict
	for _, q := range []int{0, -3, 5} {
		if _, err := s.Use("u1", "c1", q, now); !errors.Is(err, ErrConflict) {
			t.Fatalf("qty %d: want ErrConflict, got %v", q, err)
		}
	}
	// 承诺编号为空 / 不存在 / 指向另一承诺 → ErrConflict
	for _, cid := range []string{"", "cMissing", "c2"} {
		if _, err := s.Use("u1", cid, 2, now); !errors.Is(err, ErrConflict) {
			t.Fatalf("commit %q: want ErrConflict, got %v", cid, err)
		}
	}
	// 状态未被冲突提交改变：实物 8、c1 已用 2、有效占用 3
	p, _ := s.Part("part1")
	if p.Stock != 8 {
		t.Fatalf("stock = %d, want 8", p.Stock)
	}
	c1, _ := s.Commitment("c1")
	if c1.Used != 2 || c1.Expired || c1.Canceled {
		t.Fatalf("c1 = %+v", c1)
	}
	c2, _ := s.Commitment("c2")
	if c2.Used != 0 || c2.Expired {
		t.Fatalf("c2 = %+v", c2)
	}
	// 冲突提交不得借当前时刻确认原承诺到期
	if _, err := s.Use("u1", "c1", 0, now.Add(100*24*time.Hour)); !errors.Is(err, ErrConflict) {
		t.Fatalf("late conflict: got %v", err)
	}
	c1, _ = s.Commitment("c1")
	if c1.Expired {
		t.Fatal("conflict submission confirmed expiry")
	}
	// 取消原承诺后，冲突仍按编号冲突处理
	if _, err := s.Cancel("c2", now); err != nil {
		t.Fatal(err)
	}
	if _, err := s.Use("u1", "c2", 2, now); !errors.Is(err, ErrConflict) {
		t.Fatalf("canceled target: got %v", err)
	}
	// 原样重试（含更晚时刻、原承诺已取消）仍取回首次成功记录
	if _, err := s.Cancel("c1", now); err != nil {
		t.Fatal(err)
	}
	u, err := s.Use("u1", "c1", 2, now.Add(200*24*time.Hour))
	if err != nil || u.ID != "u1" || u.CommitmentID != "c1" || u.Quantity != 2 {
		t.Fatalf("retry: u=%+v err=%v", u, err)
	}
	p, _ = s.Part("part1")
	if p.Stock != 8 {
		t.Fatalf("stock after retry = %d, want 8", p.Stock)
	}
	// 无成功记录的编号：保留原有错误分类，失败不占用编号
	if _, err := s.Use("u2", "", 1, now); !errors.Is(err, ErrInvalidParam) {
		t.Fatalf("empty commit: got %v", err)
	}
	if _, err := s.Use("u2", "c1", 0, now); !errors.Is(err, ErrInvalidParam) {
		t.Fatalf("zero qty: got %v", err)
	}
	if _, err := s.Use("u2", "cMissing", 1, now); !errors.Is(err, ErrNotFound) {
		t.Fatalf("unknown commit: got %v", err)
	}
	if _, err := s.Use("u2", "c1", 1, now); !errors.Is(err, ErrCommitmentClosed) {
		t.Fatalf("canceled commit: got %v", err)
	}
	if _, err := s.Use("u2", "cMissing", 0, now); !errors.Is(err, ErrInvalidParam) {
		t.Fatalf("invalid param precedence: got %v", err)
	}
}
EOF
